const openAdminAlert = `-- name: OpenAdminAlert :one
INSERT INTO admin_alerts (kind, station_id, reason, product_id, details)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (kind, station_id, reason, product_id) WHERE resolved_at IS NULL DO NOTHING
RETURNING id
`

type OpenAdminAlertParams struct {
	Kind      AdminAlertKind `json:"kind"`
	StationID uuid.UUID      `json:"stationId"`
	Reason    *ReportReason  `json:"reason"`
	ProductID *int16         `json:"productId"`
	Details   []byte         `json:"details"`
}

// Une seule alerte ouverte par cause : rien n'est créé si elle existe déjà.
func (q *Queries) OpenAdminAlert(ctx context.Context, arg OpenAdminAlertParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, openAdminAlert,
		arg.Kind,
		arg.StationID,
		arg.Reason,
		arg.ProductID,
		arg.Details,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const resolveAdminAlert = `-- name: ResolveAdminAlert :execrows
UPDATE admin_alerts SET resolved_at = now(), resolved_by = $1, resolution = $2
WHERE id = $3 AND resolved_at IS NULL
`

type ResolveAdminAlertParams struct {
	ResolvedBy *uuid.UUID `json:"resolvedBy"`
	Resolution *string    `json:"resolution"`
	ID         uuid.UUID  `json:"id"`
}

func (q *Queries) ResolveAdminAlert(ctx context.Context, arg ResolveAdminAlertParams) (int64, error) {
	result, err := q.db.Exec(ctx, resolveAdminAlert, arg.ResolvedBy, arg.Resolution, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

